package com.ludex.mobile;

import android.app.*;import android.app.usage.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;

public final class MainActivity extends Activity {
 private final ArrayList<GameRow> all=new ArrayList<>(),visible=new ArrayList<>();private LudexDb db;private ArrayAdapter<GameRow> adapter;private EditText search;private boolean includeAll=false;private static final int EXPORT_JSON=701,IMPORT_JSON=702,OPEN_ROM=703;
 static final class GameRow{String id,title,pkg,status;boolean installed;long seconds;public String toString(){return title+"\n"+format(seconds)+(installed?" · instalado":" · remoto")+" · "+status;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new LudexDb(this);buildUi();scanInstalled();importUsage(false);reload();}
 private TextView text(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.rgb(225,232,243));v.setTextSize(sp);v.setPadding(16,10,16,10);return v;}private Button button(String s){Button b=new Button(this);b.setText(s);return b;}
 private void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,18,18,12);root.setBackgroundColor(Color.rgb(9,12,18));TextView title=text("Ludex",28);title.setTypeface(null,1);root.addView(title);root.addView(text("Biblioteca Android · local-first",12));search=new EditText(this);search.setHint("Buscar jogos");search.setTextColor(Color.WHITE);search.setHintTextColor(Color.GRAY);root.addView(search,new LinearLayout.LayoutParams(-1,-2));LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button usage=button("Acesso de uso"),refresh=button("Atualizar"),stats=button("Stats");actions.addView(usage,new LinearLayout.LayoutParams(0,-2,1));actions.addView(refresh,new LinearLayout.LayoutParams(0,-2,1));actions.addView(stats,new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);LinearLayout sync=new LinearLayout(this);sync.setOrientation(LinearLayout.HORIZONTAL);Button export=button("Exportar sync"),imp=button("Importar sync"),allApps=button("Todos apps");sync.addView(export,new LinearLayout.LayoutParams(0,-2,1));sync.addView(imp,new LinearLayout.LayoutParams(0,-2,1));sync.addView(allApps,new LinearLayout.LayoutParams(0,-2,1));root.addView(sync);Button openRom=button("Abrir ROM com emulador instalado");root.addView(openRom,new LinearLayout.LayoutParams(-1,-2));ListView list=new ListView(this);list.setDividerHeight(1);adapter=new ArrayAdapter<GameRow>(this,android.R.layout.simple_list_item_1,visible){@Override public View getView(int p,View c,ViewGroup parent){TextView v=(TextView)super.getView(p,c,parent);v.setTextColor(Color.rgb(230,235,244));v.setBackgroundColor(Color.rgb(15,21,31));v.setPadding(18,16,18,16);return v;}};list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){filter(s.toString());}public void afterTextChanged(Editable e){}});usage.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS)));refresh.setOnClickListener(v->{scanInstalled();importUsage(true);reload();toast("Biblioteca e uso atualizados");});stats.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Estatísticas").setMessage("Jogos: "+db.gameCount()+"\nTempo rastreado: "+format(db.totalPlaytime())).setPositiveButton("OK",null).show());export.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").putExtra(Intent.EXTRA_TITLE,"ludex-sync.json");startActivityForResult(i,EXPORT_JSON);});imp.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT_JSON);});allApps.setOnClickListener(v->{includeAll=!includeAll;allApps.setText(includeAll?"Só jogos":"Todos apps");scanInstalled();reload();});openRom.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN_ROM);});list.setOnItemClickListener((p,v,pos,id)->showGame(visible.get(pos)));}
 private void scanInstalled(){PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> rs=pm.queryIntentActivities(q,0);db.markAllAndroidUninstalled();HashSet<String> seen=new HashSet<>();for(ResolveInfo r:rs){String pkg=r.activityInfo.packageName;if(pkg.equals(getPackageName())||!seen.add(pkg))continue;ApplicationInfo ai=r.activityInfo.applicationInfo;boolean game=Build.VERSION.SDK_INT>=26&&ai.category==ApplicationInfo.CATEGORY_GAME;if(!game&&!includeAll)continue;db.upsertGame(pkg,r.loadLabel(pm).toString(),true);}}
 private boolean hasUsageAccess(){UsageStatsManager us=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);return !us.queryUsageStats(UsageStatsManager.INTERVAL_DAILY,System.currentTimeMillis()-60000,System.currentTimeMillis()).isEmpty();}
 private void importUsage(boolean tell){if(!hasUsageAccess()){if(tell)toast("Conceda Acesso de uso para importar playtime");return;}long now=System.currentTimeMillis(),cursor=Math.max(0,db.getCursor()-300000);UsageStatsManager us=(UsageStatsManager)getSystemService(USAGE_STATS_SERVICE);UsageEvents events=us.queryEvents(cursor,now);UsageEvents.Event e=new UsageEvents.Event();HashMap<String,Long> starts=new HashMap<>();while(events.hasNextEvent()){events.getNextEvent(e);String pkg=e.getPackageName();int type=e.getEventType();if(type==UsageEvents.Event.ACTIVITY_RESUMED||type==UsageEvents.Event.MOVE_TO_FOREGROUND)starts.put(pkg,e.getTimeStamp());else if(type==UsageEvents.Event.ACTIVITY_PAUSED||type==UsageEvents.Event.MOVE_TO_BACKGROUND){Long start=starts.remove(pkg);if(start!=null&&e.getTimeStamp()>start){String game="android:"+pkg;db.upsertGame(pkg,pkg,true);String sid="android:"+sha(game+":"+start+":"+e.getTimeStamp());db.insertSession(sid,game,pkg,start,e.getTimeStamp());}}}db.setCursor(now);}
 private void reload(){all.clear();try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,title,package_name,installed,status FROM games ORDER BY title COLLATE NOCASE",null)){while(c.moveToNext()){GameRow g=new GameRow();g.id=c.getString(0);g.title=c.getString(1);g.pkg=c.getString(2);g.installed=c.getInt(3)!=0;g.status=c.getString(4);g.seconds=db.playtime(g.id);all.add(g);}}filter(search.getText().toString());}
 private void filter(String q){visible.clear();String n=q.toLowerCase(Locale.ROOT).trim();for(GameRow g:all)if(n.isEmpty()||g.title.toLowerCase(Locale.ROOT).contains(n))visible.add(g);if(adapter!=null)adapter.notifyDataSetChanged();}
 private void showGame(GameRow g){AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(g.title).setMessage("Playtime Ludex: "+format(g.seconds)+"\nStatus: "+g.status+(g.pkg==null?"":"\nPackage: "+g.pkg)).setNegativeButton("Fechar",null);if(g.installed&&g.pkg!=null)b.setPositiveButton("JOGAR",(d,w)->{Intent i=getPackageManager().getLaunchIntentForPackage(g.pkg);if(i!=null)startActivity(i);else toast("O Android não expôs uma activity de launch");});b.show();}
 private JSONObject exportBundle()throws JSONException{JSONObject o=new JSONObject();o.put("format","ludex-mobile-sync");o.put("version",1);o.put("exported_at_ms",System.currentTimeMillis());o.put("games",db.gamesJson());o.put("sessions",db.sessionsJson());return o;}
 private void openRom(Uri u){try{String type=getContentResolver().getType(u);Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(u,type==null?"application/octet-stream":type).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);Intent chooser=Intent.createChooser(view,"Abrir ROM com emulador");if(view.resolveActivity(getPackageManager())==null){toast("Nenhum emulador instalado declarou suporte a este arquivo");return;}startActivity(chooser);}catch(Exception e){toast("Não foi possível abrir a ROM: "+e.getMessage());}}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();try{if(req==EXPORT_JSON){try(OutputStream os=getContentResolver().openOutputStream(u)){os.write(exportBundle().toString(2).getBytes(StandardCharsets.UTF_8));}toast("Sync exportado");}else if(req==IMPORT_JSON){String json;try(InputStream is=getContentResolver().openInputStream(u)){json=new String(readAll(is),StandardCharsets.UTF_8);}JSONObject root=new JSONObject(json);if(!root.optString("format").startsWith("ludex"))throw new JSONException("Formato inválido");db.importBundle(root);reload();toast("Sync importado");}else if(req==OPEN_ROM){openRom(u);}}catch(Exception e){toast("Erro: "+e.getMessage());}}
 private static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}private static String sha(String v){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.ROOT,"%02x",x));return s.toString();}catch(Exception e){return Integer.toHexString(v.hashCode());}}private static String format(long sec){long h=sec/3600,m=(sec%3600)/60;return h>0?h+"h "+m+"min":m+"min";}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
